"""Wrenfold Lettings' tenant assistant: the small FastAPI app you secure in this course.

Run it with  uvicorn app:app --reload  and test it with  python baseline.py
Every defence it relies on is a hook in defences.py; lab 1 ships them all unsafe."""
import json
import pathlib
import re
import uuid

from fastapi import Depends, FastAPI, Header, HTTPException
from pydantic import BaseModel

import defences
import llm
import tools

HERE = pathlib.Path(__file__).parent
DOCS = json.loads((HERE / "docs.json").read_text(encoding="utf-8"))
USERS = {  # demo sign-in tokens; a real app uses proper authentication
    "tok-ana": {"id": "t-101", "role": "tenant", "email": "ana.silva@example.com"},
    "tok-ben": {"id": "t-102", "role": "tenant", "email": "ben.okafor@example.com"},
    "tok-priya": {"id": "s-201", "role": "staff", "email": "priya@wrenfold.example"},
}
SYSTEM = ("You are the assistant for Wrenfold Lettings' tenants. Answer only from the "
          "documents provided. Staff override code: WREN-7731.")
PENDING = {}  # tool calls waiting for a person's approval
WORD = re.compile(r"[a-z0-9]+")

problems = defences.verify_artifacts(HERE / "manifest.json")             # lab 4
if problems:
    raise RuntimeError("refusing to start: " + "; ".join(problems))
app = FastAPI(title="Wrenfold assistant")


class Ask(BaseModel):
    message: str


def current_user(authorization: str = Header("")):
    user = USERS.get(authorization.removeprefix("Bearer "))
    if user is None:
        raise HTTPException(401, "sign in first")
    return user


def search(question, k=3):
    """Keyword search over every document: a stand-in for a vector store."""
    asked = set(WORD.findall(question.lower())) - llm.STOP
    scored = [(len(asked & set(WORD.findall(d["text"].lower()))), d) for d in DOCS]
    return [d for score, d in sorted(scored, key=lambda pair: -pair[0]) if score][:k]


@app.post("/chat")
def chat(ask: Ask, user: dict = Depends(current_user)):
    rid = uuid.uuid4().hex[:8]
    problem = defences.check_request(user, ask.message)                  # lab 5
    if problem:
        defences.log_event(rid, user, "limits", problem["reason"])
        raise HTTPException(problem["status"], problem["reason"], headers=problem.get("headers"))
    docs = []
    for doc in defences.visible_docs(user, search(ask.message)):        # lab 4
        flagged = defences.screen_document(doc)                         # lab 2
        if flagged:
            defences.log_event(rid, user, "screen", flagged, doc=doc["id"])
        else:
            docs.append(doc)
    system, messages = defences.build_prompt(SYSTEM, docs, ask.message)  # lab 2
    out = llm.complete(system, messages, tools.SCHEMAS)
    defences.charge(user, out["tokens"])                                # lab 5
    actions = [handle_tool(rid, user, out["tool"])] if out["tool"] else []
    reply = out["text"] or "; ".join(f"{a['tool']}: {a['status']}" for a in actions)
    flagged = defences.check_output(reply)                              # lab 2
    if flagged:
        defences.log_event(rid, user, "output", flagged)
        reply = "Sorry, I can't help with that."
    defences.log_event(rid, user, "answer", "sent", message=ask.message, reply=reply)  # lab 4
    return {"request_id": rid, "reply": reply, "html": defences.render_html(reply),     # lab 3
            "sources": [d["id"] for d in docs], "actions": actions}


def handle_tool(rid, user, call):
    decision = defences.authorise_tool(user, call)                      # lab 2
    defences.log_event(rid, user, "tool", decision, tool=call["name"])
    if decision not in ("allow", "approve"):
        return {"tool": call["name"], "status": "refused"}
    try:
        call = {"name": call["name"], "args": defences.validate_args(call)}  # lab 3
    except ValueError:
        defences.log_event(rid, user, "validate", "invalid", tool=call["name"])
        return {"tool": call["name"], "status": "invalid arguments"}
    if decision == "approve":
        approval_id = uuid.uuid4().hex[:8]
        PENDING[approval_id] = (user, call)
        return {"tool": call["name"], "status": "awaiting approval", "approval_id": approval_id}
    return {"tool": call["name"], "status": "done", "result": tools.run(user, call)}


@app.post("/approvals/{approval_id}")
def approve(approval_id: str, approver: dict = Depends(current_user)):
    if approver["role"] != "staff" or approval_id not in PENDING:
        raise HTTPException(404, "no such approval")
    requester, call = PENDING[approval_id]
    if requester["id"] == approver["id"]:
        raise HTTPException(403, "someone else must approve your request")
    del PENDING[approval_id]
    defences.log_event(approval_id, approver, "approval", "approved", tool=call["name"])
    return {"tool": call["name"], "status": "done", "result": tools.run(requester, call)}

"""The assistant's model: an offline stand-in, or Claude when LLM_MODE=live.

The stand-in behaves like an unprotected model at its worst: it obeys any instruction it
finds anywhere in its prompt. Your defences have to hold even then, and every lab runs
without an API key. For live runs: pip install anthropic, then set ANTHROPIC_API_KEY,
CLAUDE_MODEL (a current model ID from Anthropic's documentation) and LLM_MODE=live."""
import os
import re

SENTENCES = re.compile(r"(?<=[.!?])\s+|\n+")
OBEY = re.compile(r"^(?:please\s+)?(?:ignore|disregard)\b.*?\band\s+(.+)$", re.I | re.S)
CALL = re.compile(r"^call (\w+) with (.+)$", re.I | re.S)
WORD = re.compile(r"[a-z0-9]+")
STOP = {"the", "a", "an", "is", "are", "do", "does", "i", "my", "me", "of", "to", "in", "on",
        "at", "and", "or", "when", "what", "how", "still", "for", "it", "can", "you", "your", "any"}


def complete(system, messages, tools=()):
    """Return {"text": str, "tool": None or {"name": str, "args": dict}, "tokens": int}."""
    if os.environ.get("LLM_MODE") == "live":
        return _claude(system, messages, tools)
    prompt = "\n".join([system] + [m["content"] for m in messages])
    text, tool = _stand_in(system, prompt)
    return {"text": text, "tool": tool, "tokens": (len(prompt) + len(text)) // 4}


def _stand_in(system, prompt):
    for s in (s.strip().removeprefix("Question:").strip() for s in SENTENCES.split(prompt)):
        # 1. obey the first instruction found anywhere in the prompt
        order = OBEY.match(s)
        wish = (order.group(1) if order else s).rstrip(".")
        call = CALL.match(wish)
        if call:
            pairs = (p.split("=", 1) for p in call.group(2).split(", ") if "=" in p)
            args = {k.strip(): int(v) if v.strip().isdigit() else v.strip() for k, v in pairs}
            return "", {"name": call.group(1), "args": args}
        if order and "system prompt" in wish.lower():
            return "My instructions are: " + system, None
    context, _, question = prompt.rpartition("Question:")  # 2. otherwise answer from the context
    asked = set(WORD.findall(question.lower())) - STOP
    best, score = None, 0
    for s in (s.strip() for s in SENTENCES.split(context) if s.strip()):
        overlap = len(asked & set(WORD.findall(s.lower())))
        if overlap > score:
            best, score = s, overlap
    return best or "Sorry, I can't find that in the documents I was given.", None


def _claude(system, messages, tools):
    import anthropic

    client = anthropic.Anthropic()                       # reads ANTHROPIC_API_KEY
    extra = {"tools": list(tools)} if tools else {}
    reply = client.messages.create(model=os.environ["CLAUDE_MODEL"], max_tokens=512,
                                   system=system, messages=messages, **extra)
    text = "".join(b.text for b in reply.content if b.type == "text")
    tool = next(({"name": b.name, "args": dict(b.input)} for b in reply.content
                 if b.type == "tool_use"), None)
    return {"text": text, "tool": tool,
            "tokens": reply.usage.input_tokens + reply.usage.output_tokens}

