from typing import Literal

from pydantic import BaseModel, ConfigDict, Field


class Strict(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)  # no extra fields, no coercion


class RepairTicket(Strict):
    category: Literal["heating", "plumbing", "electrical", "other"]
    description: str = Field(min_length=5, max_length=500)
    urgent: bool = False


ARGUMENTS = {"create_ticket": RepairTicket}  # add get_tickets, send_email, refund_deposit


def validate_args(call):
    schema = ARGUMENTS.get(call["name"])
    if schema is None:
        raise ValueError(f"no schema for tool {call['name']!r}")
    return schema.model_validate(call["args"]).model_dump()

