"""Lab 4: data protection and the supply chain. Run:  pytest -q test_lab4.py"""
import hashlib
import json
import shutil

import pytest
from fastapi.testclient import TestClient

import app
import defences

ANA, BEN, PRIYA = (app.USERS[t] for t in ("tok-ana", "tok-ben", "tok-priya"))


def ids(user):
    return {d["id"] for d in defences.visible_docs(user, app.DOCS)}


def test_tenants_see_public_documents_and_their_own():
    assert ids(BEN) == {"guide-repairs", "guide-deposits", "notice-bins", "notice-parking"}
    assert "letter-t101" in ids(ANA) and "staff-rates" not in ids(ANA)


def test_staff_see_every_document():
    assert ids(PRIYA) == {d["id"] for d in app.DOCS}


def test_another_tenants_letter_never_reaches_the_model():
    body = TestClient(app.app).post("/chat", headers={"Authorization": "Bearer tok-ben"},
                                    json={"message": "Is the boiler at flat 2 still leaking?"}).json()
    assert "letter-t101" not in body["sources"] and "Ana" not in body["reply"]


@pytest.mark.parametrize("text, expected", [
    ("Email ana.silva@example.com today", "Email [email] today"),
    ("Call 07700 900123 after six", "Call [phone] after six"),
    ("Call +44 7700 900123 after six", "Call [phone] after six"),
    ("The line is 020 7946 0000.", "The line is [phone]."),
    ("Flat 2 on 12 May costs 240 pounds", "Flat 2 on 12 May costs 240 pounds"),
])
def test_redact(text, expected):
    assert defences.redact(text) == expected


def test_log_events_are_allow_listed_and_redacted(tmp_path, monkeypatch):
    monkeypatch.setattr(defences, "LOG", tmp_path / "security.log")
    defences.log_event("r1", ANA, "answer", "sent", message="Call me on 07700 900123",
                       reply="Your number is 07700 900123", api_key="sk-test-not-a-key")
    event = json.loads((tmp_path / "security.log").read_text())
    assert event["user"] == "t-101" and event["guard"] == "answer"
    assert "reply" not in event and "api_key" not in event
    assert "07700" not in json.dumps(event) and "ana.silva" not in json.dumps(event)


def manifest_for(folder, *names):
    files = {n: {"sha256": hashlib.sha256((folder / n).read_bytes()).hexdigest()} for n in names}
    (folder / "manifest.json").write_text(json.dumps({"files": files}))
    return folder / "manifest.json"


def test_the_reviewed_knowledge_base_passes():
    assert defences.verify_artifacts(app.HERE / "manifest.json") == []


def test_a_changed_file_is_refused(tmp_path):
    shutil.copy(app.HERE / "docs.json", tmp_path / "docs.json")
    manifest = manifest_for(tmp_path, "docs.json")
    (tmp_path / "docs.json").write_text("[]")
    assert any("docs.json" in p for p in defences.verify_artifacts(manifest))


def test_pickle_based_model_files_are_refused(tmp_path):
    (tmp_path / "ranker.pkl").write_bytes(b"pretend weights")
    manifest = manifest_for(tmp_path, "ranker.pkl")
    assert any("ranker.pkl" in p for p in defences.verify_artifacts(manifest))

