MAX_CHARS = 4000
RATE_LIMIT, WINDOW = 5, 60.0     # requests per user in any 60 seconds
DAILY_TOKENS = 20_000
_recent, _spent = {}, {}         # user ID -> request times; (user ID, day) -> tokens


def check_request(user, message):
    now = time.monotonic()
    if len(message) > MAX_CHARS:
        return {"status": 413, "reason": f"message longer than {MAX_CHARS} characters"}
    recent = [t for t in _recent.get(user["id"], []) if now - t < WINDOW]
    if len(recent) >= RATE_LIMIT:
        wait = int(WINDOW - (now - recent[0])) + 1
        return {"status": 429, "reason": "rate limit", "headers": {"Retry-After": str(wait)}}
    # refuse with 429 when today's tokens for this user have reached DAILY_TOKENS
    _recent[user["id"]] = recent + [now]
    return None

